<?php
require __DIR__.'/bootstrap.php';
require_once __DIR__.'/../services/PasskeySignatureGuard.php';
$id=(int)($_GET['id']??$_POST['id']??0);$c=$contractManager->get($id);if(!$c){http_response_code(404);exit('Contrat introuvable');}
if($c['statut']==='brouillon'){header('Location: workflow.php?id='.$id);exit;}
$_SESSION['contract_csrf']=$_SESSION['contract_csrf']??bin2hex(random_bytes(24));$error='';
$q=$pdo->prepare('SELECT personnel_id FROM user_devis_banamur WHERE id=? AND active=1');$q->execute([(int)($_SESSION['user_id']??0)]);$currentPersonnelId=(int)$q->fetchColumn();
$canManage=hasPermission('acces_admin')||hasPermission('acces_rh');
$stages=$contractManager->workflow($id);
$canSee=$canManage||($currentPersonnelId>0&&($currentPersonnelId===(int)$c['signataire_banamur_personnel_id']||in_array($currentPersonnelId,array_map('intval',array_column($stages,'signataire_personnel_id')),true)));
if(!$canSee){http_response_code(403);exit('Ce contrat ne vous est pas attribué.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!hash_equals((string)$_SESSION['contract_csrf'],(string)($_POST['_csrf']??'')))throw new RuntimeException('Session expirée.');
  if(($_POST['action']??'')==='set_signer')$contractManager->setFinalSigner($id,(int)($_POST['signataire_banamur_personnel_id']??0),(int)$_SESSION['user_id'],$canManage);
  else{
   $party=(string)($_POST['party']??'');$hash=(string)($_POST['document_hash']??'');
   if(!in_array($party,['banamur','prestataire'],true))throw new RuntimeException('Partie invalide.');
   $signatureProof=PasskeySignatureGuard::requireVerified((int)$_SESSION['user_id'],'contract_final:'.$id.':'.$party.':'.$hash);
   $contractManager->signFinal($id,$party,(string)($_POST['signature']??''),(int)$_SESSION['user_id'],$currentPersonnelId,$canManage,$hash,$signatureProof);
  }
  header('Location: signer.php?id='.$id);exit;
 }catch(Throwable $e){$error=$e->getMessage();}
}
$documentHash=ContractWorkflowPolicy::finalHash($contractManager->get($id),$contractManager->workflow($id));
$c=$contractManager->get($id);$personnel=$pdo->query("SELECT p.id_personnel_soignant id,p.nom_personnel_soignant nom,p.matricule_personnel_soignant matricule,COALESCE(NULLIF(f.lib_fonction,''),'Fonction non renseignée') fonction,COALESCE(NULLIF(p.email_personnel_soignant,''),(SELECT NULLIF(u.mail_pro,'') FROM user_devis_banamur u WHERE u.personnel_id=p.id_personnel_soignant AND u.active=1 ORDER BY u.id LIMIT 1)) email FROM personnel p LEFT JOIN fonction f ON f.id_fonction=p.fonction_id WHERE (p.date_sortie IS NULL OR p.date_sortie='0000-00-00') AND UPPER(COALESCE(f.lib_fonction,'')) LIKE '%DIRECTEUR GENERAL%' ORDER BY p.nom_personnel_soignant")->fetchAll(PDO::FETCH_ASSOC);$pageTitle='Signatures '.$c['reference'];$activeMenu='contrats';require __DIR__.'/../decaissement/includes/header.php';require __DIR__.'/../decaissement/includes/navbar.php';?>
<link rel="stylesheet" href="contract-theme.css?v=<?= filemtime(__DIR__ . '/contract-theme.css') ?>">
<script>document.body.classList.add('contract-brand');</script>

<?php if($canManage && empty($c['signature_banamur']) && empty($c['signature_prestataire'])): ?><script type="application/json" id="contractPersonnelData"><?=json_encode($personnel,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP)?></script><form method="post" id="contractSignerForm" class="mx-auto mt-6 max-w-4xl rounded-3xl border contract-border contract-soft p-5"><input type="hidden" name="_csrf" value="<?=$h($_SESSION['contract_csrf'])?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="set_signer"><div class="relative" id="contractSignerCombobox"><label for="contractSignerSearch" class="block font-black">Signataire de l’entreprise du contrat</label><input type="hidden" name="signataire_banamur_personnel_id" id="contractSignerId" value="<?=(int)($c['signataire_banamur_personnel_id']??0)?:''?>"><div class="relative mt-2"><i class="fas fa-magnifying-glass pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 contract-reference"></i><input id="contractSignerSearch" type="search" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="contractSignerResults" autocomplete="off" placeholder="Saisir un nom, une fonction ou un matricule…" class="w-full rounded-2xl border contract-border bg-white py-3.5 pl-11 pr-12 font-semibold outline-none transition focus:contract-border focus:ring-4 focus:contract-ring"><i class="fas fa-chevron-down pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-slate-400"></i></div><div id="contractSignerResults" role="listbox" class="absolute z-50 mt-2 hidden max-h-72 w-full overflow-y-auto rounded-2xl border border-slate-200 bg-white p-2 shadow-2xl"></div><p id="contractSignerHelp" class="mt-2 text-xs contract-reference">Recherchez puis sélectionnez la personne dans ce même champ.</p></div><button class="mt-4 rounded-xl contract-primary px-5 py-3 font-black text-white">Enregistrer le signataire</button></form>
<?php endif; ?><main class="mx-auto max-w-4xl px-4 py-8"><header class="contract-hero p-6"><p class="text-xs font-black uppercase contract-eyebrow">Signature électronique</p><h1 class="mt-2 text-3xl font-black"><?=$h($c['reference'])?></h1><p class="text-slate-300"><?=$h($c['objet'])?></p></header><?php if($error):?><div class="mt-4 rounded-xl bg-rose-50 p-4 text-rose-800"><?=$h($error)?></div><?php endif;?><section class="mt-6 grid gap-5 md:grid-cols-2"><?php foreach(['banamur'=>'Représentant de l’entreprise','prestataire'=>'Sous-traitant'] as $party=>$label):$signed=!empty($c['signature_'.$party]);?><form method="post" data-passkey-signature data-passkey-endpoint-base="../request" data-passkey-context="contract_final:<?=$id?>:<?=$party?>:<?=$documentHash?>" class="rounded-3xl border bg-white p-5"><input type="hidden" name="document_hash" value="<?=$documentHash?>"><input type="hidden" name="_csrf" value="<?=$h($_SESSION['contract_csrf'])?>"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="party" value="<?=$party?>"><input type="hidden" name="signature" class="signature-value"><h2 class="font-black"><?=$h($label)?></h2><?php if($signed):?><div class="mt-3 rounded-xl bg-emerald-50 p-3 font-bold text-emerald-700">Signature enregistrée et horodatée</div><img src="<?=$h($c['signature_'.$party])?>" class="mt-3 h-24 max-w-full object-contain"><?php elseif(($party==='banamur'&&$currentPersonnelId>0&&$currentPersonnelId===(int)$c['signataire_banamur_personnel_id'])||($party==='prestataire'&&$canManage&&!empty($c['signature_banamur']))):?><canvas width="460" height="160" class="signature-pad mt-3 w-full rounded-xl border bg-white"></canvas><div class="mt-3 flex gap-2"><button type="button" class="clear rounded-lg border px-3 py-2">Effacer</button><button class="rounded-lg contract-primary px-4 py-2 font-black text-white">Signer</button></div><?php else:?><p class="mt-3 text-sm text-slate-600">Signature en attente de la personne habilitée. Le prestataire signe en présence des RH après le DG.</p><?php endif;?></form><?php endforeach;?></section><a href="voir.php?id=<?=$id?>" class="mt-6 inline-block rounded-xl border bg-white px-5 py-3 font-bold">Retour au contrat</a></main><script>
document.querySelectorAll('canvas.signature-pad').forEach(canvas => {
 const ctx=canvas.getContext('2d');let down=false,drawn=false,previous=null,distance=0;
 const point=e=>{const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height]};
 canvas.style.touchAction='none';
 canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;down=true;canvas.setPointerCapture(e.pointerId);previous=point(e);ctx.beginPath();ctx.moveTo(...previous);e.preventDefault();});
 canvas.addEventListener('pointermove',e=>{if(!down)return;const p=point(e);distance+=Math.hypot(p[0]-previous[0],p[1]-previous[1]);previous=p;drawn=distance>=50;ctx.lineWidth=2.5;ctx.lineCap='round';ctx.lineTo(...p);ctx.stroke();});
 ['pointerup','pointercancel','lostpointercapture'].forEach(name=>canvas.addEventListener(name,()=>down=false));
 const form=canvas.closest('form');form.querySelector('.clear').onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);drawn=false;distance=0;form.querySelector('.signature-value').value='';};
 form.addEventListener('submit',event=>{if(!drawn){event.preventDefault();event.stopImmediatePropagation();alert('Dessinez une signature lisible avant de continuer.');return;}form.querySelector('.signature-value').value=canvas.toDataURL('image/png');});
});
</script><script src="assets/contract-signer-search.js?v=<?=time()?>"></script><?php require __DIR__.'/../decaissement/includes/footer.php';?>

